  const orient=pair=>{const forward=guestLabels.includes(pair[0])&&frameworkLabels.includes(pair[1]),reverse=guestLabels.includes(pair[1])&&frameworkLabels.includes(pair[0]);if(forward===reverse)throw pairError(forward?'ambiguous_pair_orientation':'unresolved_pair','Pair must resolve to exactly one guest pseudoatom and one framework structural label',value);return forward?[...pair]:[pair[1],pair[0]];};
  if(Array.isArray(value)){if(value.length!==2||value.some(x=>typeof x!=='string'||!x.trim()))throw pairError('invalid_atom_pair','Structured atomPair must contain exactly two nonempty strings',value);return orient(value);}
  if(typeof value!=='string'||!value.trim())throw pairError('invalid_atom_pair','Annotation atomPair is missing',value);
  if(value.includes('↔')){const parts=value.split('↔').map(x=>x.trim());if(parts.length!==2||parts.some(x=>!x)||!parts.every(x=>guestLabels.includes(x)||frameworkLabels.includes(x)))throw pairError('invalid_pair_display','Catalog pair display must contain two complete known labels',value);return orient(parts);}
